"""Text-to-SQL harness: draft -> execute -> targeted repair (at most env.max_calls policy calls).

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    # unterminated fence (truncated reply)
    m = re.search(r"```(?:sql|sqlite)?\s*(.+)$", text, re.S | re.I)
    if m and m.group(1).strip():
        return m.group(1).strip().rstrip(";").strip()
    # bare SQL in the reply
    lines = [ln for ln in text.splitlines() if ln.strip()]
    start = None
    for i, ln in enumerate(lines):
        if re.match(r"\s*(WITH|SELECT)\b", ln, re.I):
            start = i
            break
    if start is not None:
        cand = "\n".join(lines[start:]).strip().rstrip(";").strip()
        if cand:
            return cand
    return text.strip().rstrip(";").strip()


def _literals(sql):
    out = []
    for m in LITERAL.finditer(sql or ""):
        v = m.group(1).replace("''", "'")
        if v and v not in out and len(v) <= 80:
            out.append(v)
    return out[:6]


def _probe(env, sql, max_rows=20):
    try:
        r = env.execute(sql, max_rows=max_rows)
    except Exception as e:  # never let diagnostics kill the task
        return {"ok": False, "error": str(e), "rows": [], "columns": [], "n_rows": 0}
    if not isinstance(r, dict):
        return {"ok": False, "error": "no result", "rows": [], "columns": [], "n_rows": 0}
    return r


def _fmt(res, limit=8):
    if not res.get("ok"):
        return "ERROR: " + str(res.get("error"))[:300]
    rows = res.get("rows") or []
    if not rows:
        return "0 rows"
    shown = rows[:limit]
    return f"{res.get('n_rows', len(rows))} rows; first {len(shown)}: {shown}"


def _value_diagnostics(env, sql):
    """Show what is actually stored for each quoted literal used by the draft."""
    notes = []
    for lit in _literals(sql):
        core = lit.strip().strip("%_").strip()
        if len(core) < 3:
            continue
        esc = core.replace("'", "''")
        pat = "'%" + esc + "%'"
        res = _probe(
            env,
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'",
            max_rows=60,
        )
        if not res.get("ok"):
            break
        found = []
        for row in res.get("rows") or []:
            t = row[0]
            info = _probe(env, f'PRAGMA table_info("{t}")', max_rows=80)
            if not info.get("ok"):
                continue
            for col in info.get("rows") or []:
                cname = col[1]
                q = (
                    f'SELECT DISTINCT "{cname}" FROM "{t}" '
                    f'WHERE CAST("{cname}" AS TEXT) LIKE {pat} LIMIT 5'
                )
                r = _probe(env, q, max_rows=5)
                if r.get("ok") and r.get("rows"):
                    vals = [x[0] for x in r["rows"]]
                    found.append(f"{t}.{cname} = {vals!r}")
            if len(found) >= 4:
                break
        if found:
            notes.append(f"Literal {lit!r}: closest stored values -> " + "; ".join(found[:4]))
        else:
            notes.append(
                f"Literal {lit!r}: no stored value contains {core!r}; "
                "the wording/case/spelling in the question may differ from the data."
            )
    return notes


def _symmetry_diagnostic(env, sql):
    """If the draft filters on one side of a relation, test both sides."""
    m = re.search(r"\b([A-Za-z_]\w*)\s*(?:NOT\s+)?IN\s*\(\s*SELECT\s+([A-Za-z_]\w*)\s+FROM\s+([A-Za-z_]\w*)", sql, re.I)
    if not m:
        return []
    outer, col, tbl = m.group(1), m.group(2), m.group(3)
    info = _probe(env, f'PRAGMA table_info("{tbl}")', max_rows=80)
    if not info.get("ok"):
        return []
    cols = [c[1] for c in info.get("rows") or []]
    others = [c for c in cols if c.lower() != col.lower()][:3]
    notes = []
    for c in others:
        q = (
            f"SELECT {outer} FROM {tbl} WHERE {outer} NOT IN (SELECT {col} FROM {tbl}) "
            f"OR {outer} NOT IN (SELECT {c} FROM {tbl})"
        )
        r = _probe(env, q, max_rows=10)
        if r.get("ok") and r.get("rows"):
            notes.append(
                f"Relation '{tbl}' may be stored in one direction only. "
                f"Testing both columns ({col}, {c}) gives {_fmt(r, 6)}. "
                "If the question is about the absence/presence of a relationship, consider both directions."
            )
            break
    return notes


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 1000)
    schema = env.schema(task["db_id"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n"
    if desc.strip():
        user += f"\nColumn descriptions:\n{desc.strip()[:2500]}\n"
    user += f"\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}

    res = _probe(env, sql)
    ok = res.get("ok")
    nrows = res.get("n_rows", len(res.get("rows") or [])) if ok else 0
    needs_fix = (not ok) or nrows == 0

    max_calls = getattr(env, "max_calls", 2) or 2
    if needs_fix and max_calls >= 2:
        notes = []
        if not ok:
            notes.append("The query failed to execute: " + str(res.get("error"))[:300])
        else:
            notes.append("The query executed but returned 0 rows, which usually means a filter does not match the stored data.")
            notes += _value_diagnostics(env, sql)
            notes += _symmetry_diagnostic(env, sql)
        followup = (
            "Your draft query was:\n```sql\n" + sql + "\n```\n\n"
            "Execution feedback:\n- " + "\n- ".join(notes) + "\n\n"
            "Revise the query so it answers the original question against the real data. "
            "Keep the requested output columns exactly as the question asks; fix value matching "
            "(case, spacing, spelling, LIKE vs =), joins and relationship direction as needed. "
            "Do not invent tables or columns. Reply with the corrected query in a single ```sql block."
        )
        messages.append({"role": "assistant", "content": reply})
        messages.append({"role": "user", "content": followup})
        try:
            reply2 = env.chat(messages, max_tokens=max_tokens)
        except Exception:
            reply2 = ""
        sql2 = extract_sql(reply2)
        if sql2:
            res2 = _probe(env, sql2)
            if res2.get("ok"):
                n2 = res2.get("n_rows", len(res2.get("rows") or []))
                if n2 > 0 or not ok:
                    sql = sql2
    return {"sql": sql}

